char* parse_content_length(char* const buffer, const char* const end,
                int* const length)
{
        int number;
        char *p;
        int  size;

        p = buffer;
        /* search the begining of the number */
        while ( p<end && (*p==' ' || *p=='\t' ||
        (*p=='\n' && (*(p+1)==' '||*(p+1)=='\t')) ))
                p++;
        if (p==end)
                goto error;
        /* parse the number */
        size = 0;
        number = 0;
        while (p<end && *p>='0' && *p<='9') {
                number = number*10 + (*p)-'0';
                size ++;
                p++;
        }
        if (p==end || size==0)
                goto error;
        /* now we should have only spaces at the end */
        while ( p<end && (*p==' ' || *p=='\t' ||
        (*p=='\n' && (*(p+1)==' '||*(p+1)=='\t')) ))
                p++;
        if (p==end)
                goto error;
        /* the header ends proper? */
        if ( (*(p++)!='\n') && (*(p-1)!='\r' || *(p++)!='\n' ) )
                goto error;

        *length = number;
        return p;
error:
        LM_ERR("parse error near char [%d][%c]\n", *p, *p);
        return 0;
}



